import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const BIN = fileURLToPath(new URL('../bin/subtrack.js', import.meta.url));

function cli(file, ...args) {
  const r = spawnSync(process.execPath, [BIN, ...args, '--file', file], { encoding: 'utf8' });
  return { code: r.status, out: r.stdout, err: r.stderr };
}

function withFile(fn) {
  const dir = mkdtempSync(join(tmpdir(), 'subtrack-cli-'));
  try {
    fn(join(dir, 'subs.json'));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

test('add, list and total', () => withFile((file) => {
  assert.equal(cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-14').code, 0);
  assert.equal(cli(file, 'add', 'Domain name', '24', '--every', 'year', '--since', '2026-03-02').code, 0);
  const list = cli(file, 'list');
  assert.equal(list.code, 0);
  assert.match(list.out, /Netflix\s+€12\.99 monthly\s+€12\.99 a month/);
  assert.match(list.out, /Domain name\s+€24\.00 yearly\s+€2\.00 a month/);
  assert.equal(cli(file, 'total').out, 'Monthly total: €14.99 (2 plans)\n');
}));

test('list rounds what a yearly plan costs a month', () => withFile((file) => {
  cli(file, 'add', 'Cloud backup', '119.99', '--every', 'year', '--since', '2026-01-31');
  assert.match(cli(file, 'list').out, /Cloud backup\s+€119\.99 yearly\s+€10\.00 a month/);
}));

test('renewals shows what charges next', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-27');
  const r = cli(file, 'renewals', '--within', '7', '--today', '2026-10-24');
  assert.equal(r.code, 0);
  assert.equal(r.out, '27 Oct  Netflix  €12.99\n');
  assert.equal(cli(file, 'renewals', '--within', '2', '--today', '2026-10-24').out, 'Nothing renews in the next 2 days.\n');
}));

test('export writes CSV', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-27');
  assert.equal(cli(file, 'export', '--today', '2026-10-24').out,
    'name,price,cycle,monthly_cost,next_charge\nNetflix,12.99,monthly,12.99,2026-10-27\n');
}));

test('bad input exits 2 with a message', () => withFile((file) => {
  for (const args of [['add', 'X', 'abc'], ['add', 'X'], ['frobnicate'], ['renewals', '--within', 'soon'], ['add', 'X', '5', '--every', 'fortnight'], ['remove']]) {
    const r = cli(file, ...args);
    assert.equal(r.code, 2, args.join(' '));
    assert.match(r.err, /^subtrack: /, args.join(' '));
  }
}));

test('adding the same name twice fails', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99');
  const r = cli(file, 'add', 'netflix', '9.99');
  assert.equal(r.code, 1);
  assert.match(r.err, /already on the list/);
}));

test('list is sorted by name', () => withFile((file) => {
  cli(file, 'add', 'Spotify', '10.99');
  cli(file, 'add', 'Gym', '30');
  cli(file, 'add', 'Netflix', '12.99');
  assert.deepEqual(cli(file, 'list').out.trim().split('\n').map((l) => l.split(' ')[0]), ['Gym', 'Netflix', 'Spotify']);
}));

test('total --yearly is twelve months', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99');
  assert.equal(cli(file, 'total', '--yearly').out, 'Yearly total: €155.88 (1 plan)\n');
}));

test('price changes what a plan costs', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-14');
  const r = cli(file, 'price', 'netflix', '13.99');
  assert.equal(r.code, 0);
  assert.match(cli(file, 'list').out, /Netflix\s+€13\.99 monthly\s+€13\.99 a month/);
  assert.equal(cli(file, 'price', 'Hulu', '5').code, 1);
  assert.equal(cli(file, 'price', 'Netflix', 'cheap').code, 2);
}));

test('import reads back an export', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-09-27');
  cli(file, 'add', 'Domain name', '24', '--every', 'year', '--since', '2026-03-02');
  const csv = cli(file, 'export', '--today', '2026-10-24').out;
  const other = file.replace('subs.json', 'other.json');
  const csvFile = file.replace('subs.json', 'subs.csv');
  writeFileSync(csvFile, csv);
  const r = cli(other, 'import', csvFile);
  assert.equal(r.code, 0);
  assert.equal(r.out, `Imported 2 plans from ${csvFile}.\n`);
  assert.equal(cli(other, 'total').out, 'Monthly total: €14.99 (2 plans)\n');
  assert.equal(cli(other, 'import', csvFile).code, 1, 'importing the same plans twice fails');
}));

test('prices can use a decimal comma', () => withFile((file) => {
  assert.equal(cli(file, 'add', 'Spotify', '10,99').code, 0);
  assert.match(cli(file, 'list').out, /Spotify\s+€10\.99 monthly/);
}));

test('list --every shows one kind of plan', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99');
  cli(file, 'add', 'Domain name', '14', '--every', 'year');
  const out = cli(file, 'list', '--every', 'year').out;
  assert.match(out, /Domain name/);
  assert.doesNotMatch(out, /Netflix/);
}));

